)$p['id'] ?>)"><i data-lucide="copy"></i>Duplicate</button><button class="menu-item" onclick="productAction('archive',<?= (int)$p['id'] ?>)"><i data-lucide="archive"></i>Archive</button><button class="menu-item text-[#ad6763]" onclick="productAction('delete',<?= (int)$p['id'] ?>)"><i data-lucide="trash-2"></i>Delete</button></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
