<div class="editor-tab hidden" data-panel="catalogue"><div class="grid gap-4 md:grid-cols-2"><label class="field">Category<input name="category" id="f-category"></label><label class="field">Subcategory<input name="subcategory" id="f-subcategory"></label><label class="field">Brand<input name="brand" id="f-brand"></label><label class="field">Tags<input name="tags" id="f-tags" placeholder="linen, home, new"></label></div></div><div class="editor-tab hidden" data-panel="pricing"><div class="grid gap-4 md:grid-cols-2"><label class="field">Cost price<input name="cost_price" id="f-cost" type="number" min="0" step=".01"></label><label class="field">Selling price<input name="price" id="f-price" type="number" min="0" step=".01" required></label><label class="field">Compare-at price<input name="compare_at_price" id="f-compare" type="number" min="0" step=".01"></label></div></div><div class="editor-tab hidden" data-panel="inventory"><div class="grid gap-4 md:grid-cols-2"><label class="field">SKU<input name="sku" id="f-sku"></label><label class="field">Barcode<input name="barcode" id="f-barcode"></label><label class="field">Quantity<input name="quantity" id="f-quantity" type="number" min="0"></label><label class="field">Low-stock alert<input name="low_stock_alert" id="f-low" type="number" min="0" value="5"></label></div><div class="mt-5 flex flex-wrap gap-5 text-sm text-[#686b62]"><label><input type="checkbox" name="track_inventory" id="f-track" value="1" checked> Track inventory</label><label><input type="checkbox" name="allow_backorders" id="f-backorders" value="1"> Allow backorders</label><label><input type="checkbox" name="featured" id="f-featured" value="1"> Featured product</label></div></div><div class="editor-tab hidden" data-panel="shipping"><div class="grid gap-4 md:grid-cols-2"><label class="field">Weight<input name="weight" id="f-weight" type="number" step=".001"></label><label class="field">Shipping class<input name="shipping_class" id="f-shipping"></label><label class="field">Meta title<input name="meta_title" id="f-meta-title"></label><label class="field">Keywords<input name="keywords" id="f-keywords"></label><label class="field md:col-span-2">Meta description<textarea name="meta_description" id="f-meta-description" rows="4"></textarea></label></div></div><div class="mt-7 flex items-center justify-between border-t border-[#e4e4dc] pt-5"><label class="field max-w-[200px]">Visibility<select name="status" id="f-status"><option value="published" selected>Active (Published)</option><option value="draft">Draft (Hidden)</option><option value="pending">Pending</option><option value="archived">Archived</option></select></label><div class="flex gap-2"><button type="button" onclick="closeEditor()" class="rounded-xl border border-[#deded6] px-4 py-3 text-sm">Cancel</button><button class="rounded-xl bg-[#687158] px-5 py-3 text-sm text-white">Save product</button></div></div></form></div></div><div id="toast" class="fixed bottom-6 right-6 z-[60] hidden rounded-xl bg-[#252820] px-5 py-3 text-sm text-white shadow-xl"></div>
<style>.menu-item{display:flex;width:100%;align-items:center;gap:.55rem;border-radius:.55rem;padding:.55rem .65rem;text-align:left;font-size:.78rem;color:#55584f}.menu-item:hover{background:#f0f1eb}.menu-item svg{height:15px;width:15px}.field{display:grid;gap:.45rem;font-size:.75rem;color:#77796f}.field input,.field textarea,.field select{border:1px solid #deded6;background:#fff;border-radius:.7rem;padding:.7rem .8rem;color:#252820;outline:0}.field input:focus,.field textarea:focus,.field select:focus{border-color:#687158}.dropzone{display:grid;min-height:180px;place-items:center;gap:.5rem;border:1px dashed #bfc4b2;border-radius:1rem;padding:2rem;text-align:center;color:#77796f}.tab-button{color:#77796f}.tab-button.active{background:#e7ebe0;color:#536048;font-weight:600}.overflow-x-auto{padding-bottom:120px;margin-bottom:-120px}</style><script>lucide.createIcons();const csrf=<?= json_encode(csrf_token()) ?>,baseUrl=<?= json_encode($url) ?>;document.querySelectorAll('.action-button').forEach(b=>b.onclick=e=>{e.stopPropagation();const menu=document.getElementById(b.dataset.menu);if(!menu)return;const isVisible=!menu.classList.contains('hidden');document.querySelectorAll('.action-menu').forEach(m=>m.classList.add('hidden'));if(!isVisible){const rect=b.getBoundingClientRect();if(window.innerHeight - rect.bottom < 200){menu.style.top='auto';menu.style.bottom='calc(100% + 6px)'}else{menu.style.bottom='auto';menu.style.top='calc(100% + 6px)'}menu.classList.remove('hidden')}});document.addEventListener('click',()=>document.querySelectorAll('.action-menu').forEach(m=>m.classList.add('hidden')));document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.editor-tab').forEach(p=>p.classList.toggle('hidden',p.dataset.panel!==b.dataset.tab));document.querySelectorAll('.tab-button').forEach(x=>x.classList.toggle('active',x===b))});document.querySelector('[data-tab]').click();function previewProductImage(input){if(input.files&&input.files[0]){const r=new FileReader();r.onload=e=>{document.getElementById('image-preview').src=e.target.result;document.getElementById('image-preview-container').classList.remove('hidden');document.getElementById('image-dropzone-placeholder').classList.add('hidden')};r.readAsDataURL(input.files[0])}}function openEditor(id=null){document.getElementById('editor').classList.remove('hidden');document.getElementById('editor').classList.add('flex');document.getElementById('editor-title').textContent=id?'Edit product':'Add product';document.getElementById('product-form').action=id?baseUrl+'/'+id:baseUrl;document.getElementById('product-id').value=id||'';if(!id){document.getElementById('product-form').reset();document.getElementById('image-preview-container').classList.add('hidden');document.getElementById('image-dropzone-placeholder').classList.remove('hidden');document.querySelector('[data-tab="basic"]')?.click();}else{const row=document.getElementById('product-row-'+id);if(row&&row.dataset.product){try{const p=JSON.parse(row.dataset.product);document.getElementById('f-name').value=p.name||'';document.getElementById('f-slug').value=p.slug||'';document.getElementById('f-short').value=p.short_description||'';document.getElementById('f-description').value=p.description||'';document.getElementById('f-category').value=p.category||'';document.getElementById('f-subcategory').value=p.subcategory||'';document.getElementById('f-brand').value=p.brand||'';document.getElementById('f-tags').value=p.tags||'';document.getElementById('f-cost').value=p.cost_price||'';document.getElementById('f-price').value=p.price||'';document.getElementById('f-compare').value=p.compare_at_price||'';document.getElementById('f-sku').value=p.sku||'';document.getElementById('f-barcode').value=p.barcode||'';document.getElementById('f-quantity').value=p.quantity!=null?p.quantity:'';document.getElementById('f-low').value=p.low_stock_alert!=null?p.low_stock_alert:'5';document.getElementById('f-track').checked=Boolean(parseInt(p.track_inventory));document.getElementById('f-backorders').checked=Boolean(parseInt(p.allow_backorders));document.getElementById('f-featured').checked=Boolean(parseInt(p.featured));document.getElementById('f-weight').value=p.weight||'';document.getElementById('f-shipping').value=p.shipping_class||'';document.getElementById('f-meta-title').value=p.meta_title||'';document.getElementById('f-keywords').value=p.keywords||'';document.getElementById('f-meta-description').value=p.meta_description||'';document.getElementById('f-status').value=p.status||'published';if(p.featured_image){let src=p.featured_image.startsWith('http')?p.featured_image:(baseUrl.replace('/admin/products','')+p.featured_image);document.getElementById('image-preview').src=src;document.getElementById('image-preview-container').classList.remove('hidden');document.getElementById('image-dropzone-placeholder').classList.add('hidden');}else{document.getElementById('image-preview-container').classList.add('hidden');document.getElementById('image-dropzone-placeholder').classList.remove('hidden');}document.querySelector('[data-tab="basic"]')?.click();}catch(e){console.error(e);}}}}function closeEditor(){document.getElementById('editor').classList.add('hidden');document.getElementById('editor').classList.remove('flex')}async function productAction(action,id){if(action==='delete'&&!confirm('Delete this product permanently?'))return;let endpoint=action==='duplicate'?'duplicate':action==='delete'?'delete':'status';let body={_csrf:csrf,product_id:id};if(action==='archive')body.status='archived';let r=await fetch(baseUrl+'/'+endpoint,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','Accept':'application/json','X-Requested-With':'XMLHttpRequest','X-CSRF-Token':csrf},body:new URLSearchParams(body)}),d=await r.json();showToast(d.message||'Done');if(d.success)setTimeout(()=>location.reload(),450)}function showToast(m){let t=document.getElementById('toast');t.textContent=m;t.classList.remove('hidden');clearTimeout(window.toast);window.toast=setTimeout(()=>t.classList.add('hidden'),2500)}</script></body></html>


